public class JavacErrorParserTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        java.util.List<String> log = java.util.Arrays.asList(
                "Foo.java:12: error: cannot find symbol: variable x",
                "  symbol:   variable x",
                "src/Main.java:3: warning: [rawtypes] found raw type",
                "Foo.java:40: error: ';' expected",
                "Note: Foo.java uses unchecked operations.",
                "2 errors");

        check("parse an error line", new Diagnostic("Foo.java", 12, "error", "cannot find symbol: variable x"),
                JavacErrorParser.parse("Foo.java:12: error: cannot find symbol: variable x"));
        check("parse a warning line", new Diagnostic("src/Main.java", 3, "warning", "[rawtypes] found raw type"),
                JavacErrorParser.parse("src/Main.java:3: warning: [rawtypes] found raw type"));
        check("summary line is not a diagnostic", null, JavacErrorParser.parse("2 errors"));
        check("detail line is not a diagnostic", null, JavacErrorParser.parse("  symbol:   variable x"));
        check("non numeric line number", null, JavacErrorParser.parse("Foo.java:xx: error: nope"));
        check("unknown kind", null, JavacErrorParser.parse("Foo.java:9: hint: try again"));
        check("count errors", 2, JavacErrorParser.countErrors(log));
        check("first error", new Diagnostic("Foo.java", 12, "error", "cannot find symbol: variable x"),
                JavacErrorParser.firstError(log));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

