record Diagnostic(String file, int line, String kind, String message) {
}

public class JavacErrorParser {

    public static Diagnostic parse(String line) {
        if (line == null) {
            return null;
        }
        int first = line.indexOf(':');
        if (first < 0) {
            return null;
        }
        int second = line.indexOf(':', first + 1);
        if (second < 0) {
            return null;
        }
        int third = line.indexOf(':', second + 1);
        if (third < 0) {
            return null;
        }
        String file = line.substring(0, first);
        String number = line.substring(first + 1, second);
        String kind = line.substring(second + 1, third).trim();
        String message = line.substring(third + 1).trim();
        if (file.isEmpty() || file.contains(" ")) {
            return null;
        }
        if (!isDigits(number)) {
            return null;
        }
        if (!kind.equals("error") && !kind.equals("warning") && !kind.equals("note")) {
            return null;
        }
        return new Diagnostic(file, Integer.parseInt(number), kind, message);
    }

    public static int countErrors(java.util.List<String> lines) {
        int count = 0;
        if (lines == null) {
            return 0;
        }
        for (String line : lines) {
            Diagnostic diagnostic = parse(line);
            if (diagnostic != null && diagnostic.kind().equals("error")) {
                count++;
            }
        }
        return count;
    }

    public static Diagnostic firstError(java.util.List<String> lines) {
        if (lines == null) {
            return null;
        }
        for (String line : lines) {
            Diagnostic diagnostic = parse(line);
            if (diagnostic != null && diagnostic.kind().equals("error")) {
                return diagnostic;
            }
        }
        return null;
    }

    private static boolean isDigits(String text) {
        if (text.isEmpty()) {
            return false;
        }
        for (int i = 0; i < text.length(); i++) {
            if (!Character.isDigit(text.charAt(i))) {
                return false;
            }
        }
        return true;
    }
}
